// Short / long poll client: since-token + jitter + backoff.
// Why: prevents stampedes and gaps. Interval is correctness, not tuning.
async function pollLoop(state) {
  let backoffMs = 1000;
  while (true) {
    try {
      const res = await fetch(`/state?since=${state.lastId}`, { signal: AbortSignal.timeout(30000) });
      if (res.status === 200) {
        const batch = await res.json(); // [{id, payload}]
        for (const e of batch.events) {
          if (e.id > state.lastId) { apply(e); state.lastId = e.id; }
        }
        backoffMs = 1000; // reset on success
      }
      // 204 / timeout: no events, re-poll immediately for long-poll
      await sleep(jitter(2000, 500));
    } catch (err) {
      await sleep(backoffMs + Math.random() * 500);
      backoffMs = Math.min(backoffMs * 2, 30000);
    }
  }
}
function jitter(base, spread) { return base + (Math.random() * 2 - 1) * spread; }
